struct FakeClock {
    answers: RefCell<VecDeque<Instant>>,
}

impl Clock for FakeClock {
    fn now(&self) -> Instant {
        self.answers.borrow_mut().pop_front().expect("configured answer")
    }
}

let clock = FakeClock { answers: RefCell::new(VecDeque::from([epoch])) };
